import{_ as o,l as s,o as e,c as i,v as r,p as l,x as t,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"Turing 可计算","description":"","frontmatter":{"title":"Turing 可计算","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/turing-1936-paper.md","filePath":"cs/turing-1936-paper.md","lastUpdated":1789023840000}'),c={name:"cs/turing-1936-paper.md"};function u(E,a,m,P,_,A){const n=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="turing-可计算" tabindex="-1">Turing 可计算 <a class="header-anchor" href="#turing-可计算" aria-label="Permalink to &quot;Turing 可计算&quot;">​</a></h1><div class="epigraph"><p>把「一步机械手续」写成在无限纸带上的有限状态动作；不可判定随之成为定理，而不是口号。</p><footer>—— Turing, On Computable Numbers, with an Application to the Entscheidungsproblem, Proc. London Math. Soc. 1936</footer></div><p><a href="/cs/to-systems-boundary">上一课</a>（计算栈到此为止）。附录对照，不插入主干课序。主干已在<a href="/cs/to-systems-boundary">存储程序</a>、<a href="/cs/p-vs-np">P 与 NP</a>里用过「有限步骤的机械过程」与判定问题；这里对照 <strong>Turing 1936 原文的问题</strong>：希尔伯特判定问题能否有统一手续，以及用机器把「可计算」钉死。不重做停机证明的全部细节，也不把本篇插回比特课之前。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主干从比特与指令走下来，默认「程序会停或我们可以不管停」。Turing 要的缺口是先定义<strong>哪一类实数/函数算可计算</strong>：有限状态、无限带、逐步读写。Entscheidungsproblem 是：一阶逻辑有效式有没有算法。原文的贡献是模型加否定答案，不是发明电子计算机。</p><p><span class="marginnote">Church 的 λ 可定义与 Turing 机事后被证明等价。主干算法课用的是 RAM/高级语言直觉；本附录只对照纸带模型如何让「手续」变成数学对象。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>机器：状态有限，带格是符号，转移是局部的。可计算数：小数位由机器依次写出。通用机：把转移表编码到带上，一台机器模拟另一台——主干<a href="/cs/stored-program">存储程序</a>的观念亲戚，但 1936 还没有 EDVAC 的报告语言。停机、判定问题由此可以对角化。</p>',8)),(e(),l(h,null,{default:t(()=>[d(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20TM%5B%22%E6%9C%89%E9%99%90%E7%8A%B6%E6%80%81%20%2B%20%E7%BA%B8%E5%B8%A6%22%5D%20--%3E%20COMP%5B%22%E5%8F%AF%E8%AE%A1%E7%AE%97%22%5D%0A%20%20TM%20--%3E%20UNDEC%5B%22%E5%88%A4%E5%AE%9A%E9%97%AE%E9%A2%98%E6%97%A0%E7%AE%97%E6%B3%95%22%5D%0A%20%20COMP%20--%3E%20TRUNK%5B%22%E4%B8%BB%E5%B9%B2%3A%20%E7%AE%97%E6%B3%95%E4%B8%8E%20P%2FNP%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有了模型，后文才能说 P、NP、不可判定。主干<a href="/cs/p-vs-np">P 与 NP</a>已经用多项式时间当资源；1936 还没有渐近记号课里的那一套，只区分「有手续 / 无手续」。通用机让「程序即数据」在数学上先出现，工程上的存放由下一篇 EDVAC 对照。</p><h3 id="为何对照而不插入主干" tabindex="-1">为何对照而不插入主干 <a class="header-anchor" href="#为何对照而不插入主干" aria-label="Permalink to &quot;为何对照而不插入主干&quot;">​</a></h3><p>若把 1936 插进比特课之后，读者会以为本栏第一课是可计算性。主干第一课是区分与编码；可计算性是算法课后段才需要的尺子。附录只对照原文如何把手续写成机器，以及主干停机/复杂性已经取走的那一层定义。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 1936 与 1950 年《计算机器与智能》混成一篇。也不要在附录里开递归论层级。下一篇对照 von Neumann 如何把存储程序写成工程草案。</p><p>本附录不重画有限自动机与正则——那是编译课词法。Turing 机比正则强，主干正则课不需要本篇插入。</p><p>停机问题的对角线与<a href="/cs/p-vs-np">P 与 NP</a>的资源界限不是同一层：一个是有没有手续，一个是手续有多贵。</p><p>对照结束应回到主干<a href="/cs/p-vs-np">P 与 NP</a>与<a href="/cs/stored-program">存储程序</a>，而不是用纸带重讲 RISC-V。本篇不插入比特课之后。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照 Turing 1936：可计算 = 纸带上的有限手续；判定问题无解。</li><li>通用机是存储程序的数学亲戚，不是 EDVAC。</li><li>主干 P/NP 与存储程序课已取用观念，本篇不插入课序。</li><li>出处：Turing, 1936, <em>Proc. London Math. Soc.</em>。</li></ul>',11))])}const f=o(c,[["render",u]]);export{T as __pageData,f as default};
